  ui_story_31550401_62_dialog_content = "Hmph... Los Caelestites son bastante perceptivos, ¿no es así?",
  ui_story_31550401_63_dialog_content = "Cedí a impulsos tontos e hice una mala jugada.",
  ui_story_31550401_64_dialog_content = "Admito que también creo que hay algunos problemas dentro de mí.",
  ui_story_31550401_65_dialog_content = "Aunque ese estúpido dispositivo ha mejorado mi poder, también parece que me ha quitado algo.",
  ui_story_31550401_66_dialog_content = "Incluso hay momentos en que mi conciencia está en desorden, justo como cuando cometí un error elemental antes.",
  ui_story_31550401_67_dialog_content = "Además, mi ira y resentimiento por perder contra esa persona... siempre ha mantenido el fuego en mi corazón encendido.",
  ui_story_31550401_68_dialog_content = "Barton...",
  ui_story_31550401_69_dialog_content = "Si este es el precio a pagar por volverse más fuerte, estoy dispuesto a ser desgarrado.",
  ui_story_31550401_70_dialog_content = "Sabes... Tal vez, ¿hay algo en lo que pueda echarte una mano?",
  ui_story_31550401_71_dialog_content = "Eso no será necesario. Pequeños debiluchos, como tú, no serían de ninguna ayuda.",
  ui_story_31550401_72_dialog_content = "Un peón nunca puede ascender al trono confiando únicamente en fuerzas externas.",
  ui_story_31550401_73_dialog_content = "Agradezco la idea, pero se me ocurrirá algo yo mismo. Vamos, sargentos.",
  ui_story_31550401_74_dialog_content = "*Aullando*",
  ui_story_31550401_75_dialog_content = "¡Solo espera hasta que veas a un Comandante de la Legión inmensamente formidable!",
  ui_story_31550401_76_dialog_content = "¡Jajajajaja!",
  ui_story_31550401_77_dialog_content = "¿Mmm? ¿Cuándo llegaron esos dos perros aquí? Espera, ¿acaba de despegar con los perros?",
  ui_story_31550401_78_dialog_content = "Simplemente no puedo evitar sentirme preocupado...",
  ui_story_31550401_79_dialog_content = "Estamos aquí, Sargentos.",
  ui_story_31550401_80_dialog_content = "¡Awoo!",
  ui_story_31550401_81_dialog_content = "Deberías recordar este lugar, ya que aquí fue donde te ascendí a Sargento.",
  ui_story_31550401_82_dialog_content = "¡Ooowooooooooo!",
  ui_story_31550401_83_dialog_content = "¡No está mal! ¡Ese es un ladrido agradable y claro!",
  ui_story_31550401_84_dialog_content = "Ahora que el pequeño barco se ha hundido, terminaré esto por mi cuenta, ¡con ustedes dos como mis testigos!",
  ui_story_31550401_85_dialog_content = "¡Awoo!",
  ui_story_31550401_86_dialog_content = "Para enfrentar este aterrador mar una vez más...",
  ui_story_31550401_87_dialog_content = "El agua de mar intensamente fría...",
  ui_story_31550401_88_dialog_content = "Es como si intentara desgarrar mi piel y invadir mi cuerpo...",
  ui_story_31550401_89_dialog_content = "El nivel del agua ha llegado a mi pecho... Se está volviendo más difícil mover mis extremidades y respirar.",
  ui_story_31550401_90_dialog_content = "El mar parece estar tratando de restringirme... o abrazarme.",
  ui_story_31550401_91_dialog_content = "Justo como ese nuevo poder... y el creciente resentimiento que viene con un rugido.",
  ui_story_31550401_92_dialog_content = "Yo, Barton... nunca perderé contra ti.",
  ui_story_31550401_93_dialog_content = "Sí... Eso es. Usa todo tu cuerpo para abrazar el poder... así como el miedo.",
  ui_story_31550401_94_dialog_content = "...",
  ui_story_31550401_95_dialog_content = "¡...!",
  ui_story_31550401_96_dialog_content = "Maldita sea... He fallado.",
  ui_story_31550401_97_dialog_content = "Sería inútil hacer estallar el mar en pedazos... ya que el agua simplemente volverá a converger en el mar.",
  ui_story_31550401_98_dialog_content = "... Primero descansaré un poco, así que por favor vigílenme, Sargentos.",
  ui_story_31550401_99_dialog_content = "¡Awoo!",
  ui_story_31550401_100_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_31550401_101_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_31550401_102_dialog_content = "\"Realmente he experimentado algunos cambios.\"",
  ui_story_31550401_103_dialog_content = "\"Pero sé que algunas cosas no se pueden cambiar...\"",
  ui_story_31550401_104_dialog_content = "Barton...",
  ui_story_31550401_105_dialog_content = "Barton... ¿Qué es lo que te hace dudar?",
  ui_story_31550401_106_dialog_content = "O-Oficial Pango?!",
  ui_story_31550401_107_dialog_content = "¿Por qué estás aquí?! ¿No eres tú...",
  ui_story_31550401_108_dialog_content = "¿Qué estás tratando de decir? Dios, ¡mira esa cara tan fea que tienes!",
  ui_story_31550401_109_dialog_content = "¿Y te llamas soldado?",
  ui_story_31550401_110_dialog_content = "Lo siento, señor... Pero yo...",
  ui_story_31550401_111_dialog_content = "¡Sin peros! ¡Tendrás que recordar bien quién eres!",
  ui_story_31550401_112_dialog_content = "Permíteme preguntarte esto: ¿Aún recuerdas dónde están tus lealtades?",
  ui_story_31550401_113_dialog_content = "¡Por supuesto, soy la espada y el escudo de Illumina!",
  ui_story_31550401_114_dialog_content = "Bueno. Entonces, ¿qué es la gloria para ti?",
  ui_story_31550401_115_dialog_content = "¡Es nuestro honor expulsar a los Eclipsites y proteger a todos los Aurorianos!",
  ui_story_31550401_116_dialog_content = "¡Excelente! ¿Por qué luchas?",
  ui_story_31550401_117_dialog_content = "¡Esplendor Illumina!",
  ui_story_31550401_118_dialog_content = "¡Habla más alto, no puedo escucharte!!",
  ui_story_31550401_119_dialog_content = "Esplendor Ilumina!!!",
  ui_story_31550401_120_dialog_content = "¡¡Excelente!!",
  ui_story_31550401_121_dialog_content = "¿No sabes esto ya?",
  ui_story_31550401_122_dialog_content = "¡Eres un luchador, un soldado!",
  ui_story_31550401_123_dialog_content = "¡Estás rodeado de innumerables camaradas de armas que comparten los mismos intereses y creencias!",
  ui_story_31550401_124_dialog_content = "Sin embargo, ¿no solo temes ahora el formidable poder, sino que también tienes miedo de perder el control sobre él y ponerlos en peligro?",
  ui_story_31550401_125_dialog_content = "Si...",
  ui_story_31550401_126_dialog_content = "¡Eso es absurdo! ¡Atención!",
  ui_story_31550401_127_dialog_content = "¡Sí señor!",
  ui_story_31550401_128_dialog_content = "¿Crees que eres el único que puede convertirse en rey, Pequeño Barton?",
  ui_story_31550401_129_dialog_content = "Ven, Soldado, dime ¿cómo se llega a ser rey?",
  ui_story_31550401_130_dialog_content = "¡Con una determinación inquebrantable, tienes que agotar toda tu sangre y sudor para acumular suficiente poder!",
  ui_story_31550401_131_dialog_content = "¡Así es! Si puedes llegar a ser rey, ¡tus camaradas en armas también poseerán el mismo poder!",
  ui_story_31550401_132_dialog_content = "Incluso si pierdes el control y te conviertes en un \"rey loco\", ¡aún poseerán el poder para ponerte en el camino correcto!",
  ui_story_31550401_133_dialog_content = "¡Sí señor!",
  ui_story_31550401_134_dialog_content = "Mételo en tu cabeza...",
  ui_story_31550401_135_dialog_content = "¡Nunca decepciones a tus compañeros, mucho menos los subestimes!",
  ui_story_31550401_136_dialog_content = "¡¡Sí señor!!",
  ui_story_31550401_137_dialog_content = "Muy bien, entonces. Continúa y abraza tu poder que abrirá un camino completamente nuevo.",
  ui_story_31550401_138_dialog_content = "¡Nunca permitas que nuestra sangre se derrame en vano!",
  ui_story_31550401_139_dialog_content = "¡Es una orden!",
  ui_story_31550401_140_dialog_content = "¡Sí, oficial Pango!!",
  ui_story_31550401_141_dialog_content = "Wow!!",
  ui_story_31550401_142_dialog_content = "¡Awoo!!",
  ui_story_31550401_143_dialog_content = "Finalmente se levantó. ¿No te dije que iba a estar bien?",
  ui_story_31550401_144_dialog_content = "Si el impresionante Comandante de la Legión Barton se ahogara en una selva como esta,",
  ui_story_31550401_145_dialog_content = "Illumina seguramente caerá en desgracia, como Lumopolis.",
  ui_story_31550401_146_dialog_content = "¿Estás bien, Barton?",
  ui_story_31550401_147_dialog_content = "Sí, estoy bien... ¿Por qué están todos aquí?",
  ui_story_31550401_148_dialog_content = "Bueno... ¿No estás aquí para aprender a nadar?",
  ui_story_31550401_149_dialog_content = "Todos están bastante preocupados por ti después de desaparecer durante tanto tiempo sin decir nada.",
  ui_story_31550401_150_dialog_content = "Ejem, no te preocupes por mí... Estoy bien.",
  ui_story_31550401_151_dialog_content = "Incluso si no puede aprender a nadar, estoy seguro de que puede regresar cavando un túnel o algo así. Quiero decir, él es Barton, después de todo.",
  ui_story_31550401_152_dialog_content = "¡Jajaja, tienes toda la razón!",
  ui_story_31550401_153_dialog_content = "Ya que todos estamos aquí, nadie tiene permitido irse hoy. ¡Vamos, tengamos una sesión de entrenamiento de natación juntos!",
  ui_story_31550401_154_dialog_content = "Por el bien de estar preparado para cualquier posible enemigo del mar...",
  ui_story_31550401_155_dialog_content = "¡Nosotros, los Comandantes de la Legión, debemos tomar la iniciativa en aprender a nadar correctamente!",
  ui_story_31550401_156_dialog_content = "Eso es interesante. Vamos, a ver quién es el mejor entonces.",
  ui_story_31550401_157_dialog_content = "¿Eh? Pero no traje un traje de baño...",
  ui_story_31550401_158_dialog_content = "Vamos. Ha pasado mucho tiempo desde la última vez que probé los deportes acuáticos.",
  ui_story_31550401_159_dialog_content = "Simplemente... se fueron a nadar así como así...",
  ui_story_31550401_160_dialog_content = "De todos modos, lo único que importa es que Barton está bien y se ve mucho más enérgico ahora.",
  ui_story_31550401_161_dialog_content = "Sin embargo, me pregunto quién será el \"Oficial Pango\" por el que él seguía gritando en su sueño...",
  ui_story_31550401_162_dialog_content = "El nombre suena bastante familiar, aunque...",
  ui_story_31550601_1_dialog_content = "Ja, sabía que vendrías, PlayerName!",
  ui_story_31550601_2_dialog_content = "Solo porque tu mensaje sonaba tan urgente, Barton...",
  ui_story_31550601_3_dialog_content = "¡Eso es porque es urgente! ¡Mi antiguo oficial al mando finalmente ha despertado de nuevo!",
  ui_story_31550601_4_dialog_content = "Esta es una de las mejores noticias que he recibido en mi vida, y eres la primera persona con la que quería compartirla.",
  ui_story_31550601_5_dialog_content = "Y, uh... Ya que estás aquí, ¿te importaría usar tus poderes para verificar el estado mental del oficial Pango? ¡Muy agradecido!",
  ui_story_31550601_6_dialog_content = "¡Por eso me llamaste!",
  ui_story_31550601_7_dialog_content = "¿Eh? Ahora que lo pienso, no estás usando este atuendo porque—",
  ui_story_31550601_8_dialog_content = "Así es. Me preocupa que el comandante pueda no reconocerme, así que desenterré este viejo número.",
  ui_story_31550601_9_dialog_content = "Cayó en coma mientras defendía a Gannon City de los Eclipsites. Esa batalla tuvo lugar hace más de diez años.",
  ui_story_31550601_10_dialog_content = "En ese tiempo, pasé de ser un recluta punk molesto a ser el gran comandante que ves hoy! Por eso me preocupa que no me reconozca de inmediato.",
  ui_story_31550601_11_dialog_content = "Lo dudo. Después de todo, todavía eres Barton.",
  ui_story_31550601_12_dialog_content = "He intentado con todas mis fuerzas tener conversaciones con él todos estos años, con la esperanza de que algún día despertara...",
  ui_story_31550601_13_dialog_content = "Cuando recibí la llamada de repente, me quedé sin palabras.",
  ui_story_31550601_14_dialog_content = "De todos modos, estoy agradecido de que hayas venido. Vamos, entremos.",
  ui_story_31550601_15_dialog_content = "... ¡Basta de tanto pinchar y hurgar, maldita sea! Estoy perfectamente consciente de mi propio cuerpo, ¡muchas gracias!",
  ui_story_31550601_16_dialog_content = "¡Ahora déjame ir, idiotas! ¡La pelea aún no ha terminado!",
  ui_story_31550601_17_dialog_content = "¿Bartón?",
  ui_story_31550601_18_dialog_content = "¡Comandante Barton!",
  ui_story_31550601_19_dialog_content = "Oficial Pango... Realmente estás despierto...",
  ui_story_31550601_20_dialog_content = "... ¿Por qué diablos llevas puesto algo tan estúpido? No importa, llegaste justo a tiempo, diles que ya me dejen ir.",
  ui_story_31550601_21_dialog_content = "Me mantienen atrapado aquí, diciendo que es por mi propio bien o alguna tontería así.",
  ui_story_31550601_22_dialog_content = "¡También me están diciendo que la Crisis de Darkover terminó hace más de diez años! ¿Puedes creer eso?",
  ui_story_31550601_23_dialog_content = "Las líneas del frente están en grave peligro. Gannon City ha sido completamente rodeada...",
  ui_story_31550601_24_dialog_content = "Espera... Barton... ¿Cuándo empezaste a tener canas?",
  ui_story_31550601_25_dialog_content = "Oficial Pango... La batalla terminó hace mucho tiempo.",
  ui_story_31550601_26_dialog_content = "... ¿Tú también estás soltando las mismas tonterías? ¿Qué demonios está pasando aquí?",
  ui_story_31550601_27_dialog_content = "¿Y quién es ese nuevo recluta de aspecto débil? ¿Illumina ha bajado sus estándares de alistamiento otra vez?",
  ui_story_31550601_28_dialog_content = "Hola, señor. En realidad, yo soy—",
  ui_story_31550601_29_dialog_content = "¡Necesito volver a la batalla, haz que suceda ahora! ¡Esa es una orden, Barton!",
  ui_story_31550601_30_dialog_content = "¡Estoy harto de todas estas vendas y agujas! ¡Envíame de vuelta al frente de batalla, para que pueda respirar un poco de aire fresco!",
  ui_story_31550601_31_dialog_content = "Estoy seguro de que todo tendrá sentido una vez que vuelva allí...",
  ui_story_31550601_32_dialog_content = "¡Sí señor!",
  ui_story_31550601_33_dialog_content = "¿Qué piensas sobre la recuperación del Oficial Pango, PlayerName? ¿Su estado mental es... normal?",
  ui_story_31550601_34_option_content = "Sensación Pango",
  ui_story_31550601_35_dialog_content = "Espera... ¿Qué es esta sensación?",
  ui_story_31550601_36_dialog_content = "Está perfectamente bien... Solo le cuesta creer lo que dicen los demás, eso es todo.",
  ui_story_31550601_37_dialog_content = "Gracias... Vamos, señor. No es fácil para usted moverse en este momento, pero para eso están estas sillas de ruedas.",
  ui_story_31550601_38_dialog_content = "¿Qué es esto, Barton? ¿Por qué me trajiste a un museo?",
  ui_story_31550601_39_dialog_content = "Estoy seguro de que te contaron todo cuando despertaste por primera vez, oficial Pango.",
  ui_story_31550601_40_dialog_content = "Estuviste en coma durante más de una década. La crisis de Darkover también terminó hace mucho tiempo.",
  ui_story_31550601_41_dialog_content = "Como puedes ver, tu inútil subordinado ahora es el comandante de la 2da Legión.",
  ui_story_31550601_42_dialog_content = "Esto es... ¿Mi placa de identificación?",
  ui_story_31550601_43_dialog_content = "Así es, señor. Usted me dejó esto hace todos esos años.",
  ui_story_31550601_44_dialog_content = "¿Aún recuerdas aquel día? Hacia el final de la crisis, nos dijiste a todos que nos retiráramos, pero tú te quedaste para luchar.",
  ui_story_31550601_45_dialog_content = "Todos estamos a salvo ahora, señor. Todo lo que sucedió ya es cosa del pasado.",
  ui_story_31550601_46_dialog_content = "Imposible.",
  ui_story_31550601_47_dialog_content = "Y ahora, dirijamos nuestra atención a los valientes esfuerzos de la División de Máquinas de la 2ª Legión durante la Crisis de Darkover.",
  ui_story_31550601_48_dialog_content = "!",
  ui_story_31550601_49_dialog_content = "Como todos ustedes han leído antes, incluso la Ciudad Gannon cayó ante la incursión de los Eclipsites en el apogeo de la Crisis de Darkover.",
  ui_story_31550601_50_dialog_content = "Para facilitar la evacuación de la ciudad, cada miembro de la 2da Legión se quedó atrás para continuar luchando contra el enemigo.",
  ui_story_31550601_51_dialog_content = "El tanque que ves ante ti es un Modelo L3 de Illumina, y este en particular fue operado por la segunda legión durante esa batalla.",
  ui_story_31550601_52_dialog_content = "Guau-",
  ui_story_31550601_53_dialog_content = "Ese es nuestro tanque, Barton... ¿Qué le pasó? ¿Por qué está... todo destrozado?",
  ui_story_31550601_54_dialog_content = "Porque dio todo lo que tenía para salvar la ciudad de Gannon, señor, igual que usted.",
  ui_story_31550601_55_dialog_content = "A pesar de su daño, aún no se ha retirado. Vive en este museo para enseñar e inspirar a las futuras generaciones.",
  ui_story_31550601_56_dialog_content = "Este tanque es un veterano inmortal de la 2da legión.",
  ui_story_31550601_57_dialog_content = "¿Comandante Barton? No esperábamos verlo hoy, señor. Perdóneme, pero su invitado...",
  ui_story_31550601_58_dialog_content = "¿Eres... eres realmente tú? ¿El legendario guardián de la Torre Central?",
  ui_story_31550601_59_dialog_content = "¡Realmente eres tú! ¡Finalmente estás despierto, Comandante Pango!",
  ui_story_31550601_60_dialog_content = "¿Qué? ¿Realmente se despertó de su coma?",
  ui_story_31550601_61_dialog_content = "Pango? ¿Te refieres al comandante legendario que lideró un grupo de veteranos para defender la Torre Central? ¿Dónde?",
  ui_story_31550601_62_dialog_content = "¡Oficial Pango! ¿Estás seguro de que deberías estar moviéndote ahora? ¡Queremos entrenar bajo tu mando, señor!",
  ui_story_31550601_63_dialog_content = "¡Oye! ¡Muestra algo de respeto al oficial, vándalos! Si quieren hacer preguntas, háganlas una a la vez!",
  ui_story_31550601_64_dialog_content = "¡Sí señor!",
  ui_story_31550601_65_dialog_content = "¡Oficial Pango! No me conoces, pero vengo de la nueva Subciudad 13.",
  ui_story_31550601_66_dialog_content = "Si no hubiera sido por ti y el Comandante Wrath, la Subciudad 13 habría sido completamente aniquilada.",
  ui_story_31550601_67_dialog_content = "Así que gracias... Gracias por salvarnos y por darnos la oportunidad de reconstruir nuestro hogar.",
  ui_story_31550601_68_dialog_content = "¿La \"nueva\" Subciudad 13?",
  ui_story_31550601_69_dialog_content = "¡Mi turno! Saludos, oficial Pango! Nací y crecí en uno de los distritos más antiguos de la ciudad de Gannon.",
  ui_story_31550601_70_dialog_content = "Gracias a tu valentía, mi familia entera estuvo a salvo de los Eclipsites.",
  ui_story_31550601_71_dialog_content = "Solo era un niño cuando recuperamos la ciudad, ¡pero me alisté tan pronto como llegué a la mayoría de edad! Mi sueño es convertirme en un héroe como tú, ¡señor!",
  ui_story_31550601_72_dialog_content = "\"Recuperó la ciudad\"...",
  ui_story_31550601_73_dialog_content = "Muy bien, eso es suficiente por ahora. Dale algo de espacio al oficial.",
  ui_story_31550601_74_dialog_content = "¿Hmm? Bueno, si no es nuestro querido camarada, ¡el Caelestite! Bienvenido de nuevo a Illumina, mi amigo.",
  ui_story_31550601_75_dialog_content = "¡Placer de estar de vuelta!",
  ui_story_31550601_76_dialog_content = "¿Eres un Caelestite? Pero durante la Crisis de Darkover, Eraveil ya había...",
  ui_story_31550601_77_dialog_content = "... Lo sé. La verdad es que yo soy—",
  ui_story_31550601_78_dialog_content = "¡PlayerName tuvo la suerte de sobrevivir al ataque en Eraveil! ¡Algo me dice que hay muchos otros Caelestites esperándolo allá afuera!",
  ui_story_31550601_79_dialog_content = "Muchas cosas han mejorado en los años desde la crisis de Darkover, señor.",
  ui_story_31550601_80_dialog_content = "¿Así que realmente ganamos? ¿Astra realmente está en paz de nuevo?",
  ui_story_31550601_81_dialog_content = "Sí, señor. Ganamos... Aunque la paz que aseguramos no es perfecta, logramos sobrevivir a la crisis de Darkover.",
  ui_story_31550601_82_dialog_content = "Subciudad 13 fue reconstruida, junto con Ciudad Gannon. Nuestras futuras generaciones ya no se están criando en las trincheras de la guerra.",
  ui_story_31550601_83_dialog_content = "... Me vi en el espejo cuando me desperté esta mañana.",
  ui_story_31550601_84_dialog_content = "Todo ese pelo blanco en mi cabeza... Supongo que no fue por mis lesiones en absoluto.",
  ui_story_31550601_85_dialog_content = "Aun así, parece que el tiempo ha curado muchas cosas también.",
  ui_story_31550601_86_dialog_content = "A pesar de... que perdí tanto tiempo yo mismo...",
  ui_story_31550601_87_dialog_content = "Has madurado tanto en lo que parece un abrir y cerrar de ojos, Barton.",
  ui_story_31550601_88_dialog_content = "Tu entrenamiento es lo que me moldeó en un pilar de la Federación Illumina, señor.",
  ui_story_31550601_89_dialog_content = "Sé exactamente cuáles son mis deberes y lidero a nuestros soldados hacia adelante sin ninguna duda en mi corazón. La 2ª Legión está en buenas manos, así que por favor concéntrese en descansar y recuperarse, señor.",
  ui_story_31550601_90_dialog_content = "... Je. El Barton que conocía no hablaría así en absoluto.",
  ui_story_31550601_91_dialog_content = "¿Me llevarías a ver el monumento, podrías?",
  ui_story_31550601_92_dialog_content = "¡Sí señor!",
  ui_story_31550601_93_dialog_content = "También quiero ver cómo está haciendo la 2da Legión ahora.",
  ui_story_31550601_94_dialog_content = "Después de todo, alguien tiene que asegurarse de que no hayas arruinado todo.",
  ui_story_31550601_95_dialog_content = "¡Si descubro que solo estabas hablando sin sentido ahora, te someteré al mismo entrenamiento brutal que hice antes!",
  ui_story_31550601_96_dialog_content = "¡Entendido, señor!",
  ui_story_31550601_97_dialog_content = "Eh, oficial Pango...",
  ui_story_31550601_98_dialog_content = "¿Qué es?",
  ui_story_31550601_99_dialog_content = "Ha sido un honor conocerle, así como al Comandante Barton y al Caelestite.",
  ui_story_31550601_100_dialog_content = "Has sacrificado tanto para ayudarnos, y para ayudar a todo Astra.",
  ui_story_31550601_101_dialog_content = "¿Te parecería bien si... nos tomamos una foto para conmemorar este día? ¿Por favor?",
  ui_story_31550601_102_dialog_content = "Seguro.",
  ui_story_31550601_103_dialog_content = "¡Ja! Ven aquí, PlayerName! No tienes una oportunidad como esta todo el tiempo, ¡así que aprieta!",
  ui_story_31550601_104_dialog_content = "¿Una foto grupal con dos héroes de guerra legendarios? No voy a mentir, estoy un poco nervioso...",
  ui_story_31550601_105_dialog_content = "¡Lo superarás! Además, ¡eres un aliado importante en la lucha también!",
  ui_story_31550601_106_dialog_content = "¿Todos listos? ¡Bien! Ahora miren a la cámara y repitan después de mí: ¡Esplendor Illumina!",
  ui_story_31550601_107_dialog_content = "¡Esplendor Illumina!",
  ui_story_31550601_108_dialog_content = "¡Está listo! ¡Ven a mirar!",
  ui_story_31550601_109_dialog_content = "Todavía parezco muy nervioso...",
  ui_story_31550601_110_dialog_content = "Jeje, ¡y sigo siendo tan fotogénico como siempre!",
  ui_story_31550601_111_dialog_content = "...",
  ui_story_31550601_112_dialog_content = "Recuerdo haber tomado una foto así antes...",
  ui_story_31550601_113_dialog_content = "¡Ah! Es cierto... Nuestra antigua foto de grupo...",
  ui_story_31550601_114_dialog_content = "¡Bien, ahora todos sonrían ampliamente esta vez — ¡Esplendor Illumina!",
  ui_story_31550601_115_dialog_content = "<size=45>¡Esplendor Illumina!</size>",
  ui_story_31550601_116_dialog_content = "Los niños de la 2da Legión...",
  ui_story_31550601_117_dialog_content = "¿Te has convertido en las estrellas que iluminan el camino de los demás?"
}
return config
